-- Athena saved query (Product_B2C_Intl)
-- ID: 8743b4fa-c1ea-4cd4-85ba-84f92cdd73b8
-- Name: Users who saw connecting Services - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH saw_cs AS ( SELECT DISTINCT srd.rb_user_id, srd.mri_session_id, srd.route_id FROM "user_interaction"."search_route_details" srd JOIN "user_interaction"."search_details" sd ON srd.mri_session_id = sd.mri_session_id WHERE srd.__time >= TIMESTAMP '2026-05-25 18:30:00' AND srd.__time < TIMESTAMP '2026-06-21 18:30:00' AND sd.__time >= TIMESTAMP '2026-05-25 18:30:00' AND sd.__time < TIMESTAMP '2026-06-21 18:30:00' AND sd.is_connecting_service = TRUE AND sd.rb_user_id > 0 AND srd.rb_user_id > 0 AND sd.country = 'IND' AND srd.channel = 'MOBILE_APP' AND srd.tp_channel = 'INVALID' AND srd.country = 'IND' ), Txted AS ( SELECT a.mri_session_id,b.tin as prime_tin,a.source_location,a.destination_location, a.tin,prime_src_location,prime_dst_location,prime_source,prime_destination, DATE(date_add('minute', 330, a.date_of_journey)) AS doj,a.order_uuid,a.rb_user_id,a.leg, a.sales_channel,a.operator_id,DATE(date_add('minute', 330, a.date_of_issue)) as doi,a.seat_count,a.ticket_fare,layover_dp_time,layover_bp_time FROM transaction.bus_ticket_events a INNER JOIN transaction.bus_journey_events b ON a.order_uuid = b.order_uuid WHERE a.date_of_issue >= TIMESTAMP '2026-05-25 18:30:00' AND a.date_of_issue < TIMESTAMP '2026-06-21 18:30:00' AND a.is_journey = true AND a.tin IS NOT NULL AND a.country_code = 'IND' AND contains(b.tags, 'RBCONNECTED') AND a.leg in (1,2) and b.tin is not null ) SELECT DISTINCT sb.userhash FROM saw_cs s -- JOIN Txted c -- ON c.rb_user_id = sb.rb_userid JOIN "svoc"."svoc_booker" sb ON sb.rb_userid = CAST(s.rb_user_id AS VARCHAR) WHERE sb.rb_userid NOT IN (SELECT DISTINCT CAST(rb_user_id AS VARCHAR) FROM Txted) -- WHERE sb.rb_userid IN (SELECT DISTINCT CAST(rb_user_id AS VARCHAR) FROM Txted) LIMIT 150000;
